const message = $input.first().json.message;
const text = (message?.text || '').trim();
const chatId = String(message?.chat?.id || '');
const messageId = message?.message_id;
const isVoice = !!message?.voice;
const VAULT = '/home/node/obsidian-share';

const now = new Date();
const pad = n => String(n).padStart(2, '0');
const dateStr = now.getFullYear() + '-' + pad(now.getMonth()+1) + '-' + pad(now.getDate());
const timeStr = pad(now.getHours()) + ':' + pad(now.getMinutes());
const timestamp = dateStr + ' ' + timeStr;
const fileTs = now.getFullYear() + '' + pad(now.getMonth()+1) + '' + pad(now.getDate()) + '' + pad(now.getHours()) + '' + pad(now.getMinutes()) + '' + pad(now.getSeconds());

if (isVoice) {
  return [{ json: {
    command: 'voice', content: '', chatId, messageId, isVoice: true,
    dateStr, timestamp, fileTs, VAULT,
    obsidianContent: '', filepath: '', hasPrefix: false,
    replyText: "\u{1F399}\uFE0F Spraakberichten worden nog niet ondersteund. Stuur een tekstbericht of gebruik een commando."
  }}];
}

if (!text) {
  return [{ json: {
    command: 'leeg', content: '', chatId, messageId, isVoice: false,
    dateStr, timestamp, fileTs, VAULT,
    obsidianContent: '', filepath: '', hasPrefix: false,
    replyText: "Leeg bericht ontvangen. Stuur /help voor beschikbare commando's."
  }}];
}

const prefixes = [
  ['/help', 'help'], ['/commando', 'help'], ['/start', 'help'],
  ['/zoek', 'zoek'], ['/search', 'zoek'], ['/find', 'zoek'],
  ['/notitie', 'notitie'], ['/note', 'notitie'],
  ['/taak', 'taak'], ['/todo', 'taak'], ['/task', 'taak'],
  ['/idee', 'idee'], ['/idea', 'idee'],
  ['/dagboek', 'dagboek'], ['/journal', 'dagboek'],
];

let command = 'vrij';
let content = text;

for (const [prefix, cmd] of prefixes) {
  if (text.toLowerCase().startsWith(prefix + ' ') || text.toLowerCase() === prefix) {
    command = cmd;
    content = text.slice(prefix.length).trim();
    break;
  }
}

if (command === 'help') {
  const lines = [
    "<b>\u{1F9E0} Angie \u2014 Second Brain</b>",
    "",
    "<b>Directe commando's:</b>",
    "\u2022 <code>/notitie [tekst]</code> \u2014 notitie opslaan in Inbox",
    "\u2022 <code>/taak [tekst]</code> \u2014 taak toevoegen",
    "\u2022 <code>/idee [tekst]</code> \u2014 idee bewaren",
    "\u2022 <code>/dagboek [tekst]</code> \u2014 dagboek bijwerken",
    "\u2022 <code>/zoek [query]</code> \u2014 zoeken in Obsidian",
    "",
    "<b>Vrije tekst (zonder prefix):</b>",
    "De AI classificeert en structureert automatisch.",
    "",
    "<b>Voorbeelden:</b>",
    "<code>/taak rapport afmaken voor vrijdag</code>",
    "<code>/zoek project aanpak</code>",
    "<code>/idee app voor habit tracking</code>"
  ];
  return [{ json: {
    command: 'help', content: '', chatId, messageId, isVoice: false,
    dateStr, timestamp, fileTs, VAULT,
    obsidianContent: '', filepath: '', hasPrefix: false,
    replyText: lines.join('\n')
  }}];
}

if (['notitie', 'taak', 'idee'].includes(command)) {
  const tag = command;
  const bodyContent = command === 'taak' ? '- [ ] ' + content : content;
  const obsidianLines = [
    '---',
    'tags:',
    '  - ' + tag,
    '  - telegram',
    'datum: ' + timestamp,
    'bron: telegram',
    '---',
    '',
    bodyContent
  ];
  const obsidianContent = obsidianLines.join('\n');
  const filepath = VAULT + '/Inbox/' + fileTs + '-' + command + '.md';
  const labels = { notitie: 'Notitie opgeslagen', taak: 'Taak toegevoegd \u2713', idee: 'Idee opgeslagen' };
  const preview = content.length > 60 ? content.substring(0, 60) + '...' : content;
  return [{ json: {
    command, content, chatId, messageId, isVoice: false,
    dateStr, timestamp, fileTs, VAULT,
    obsidianContent, filepath, hasPrefix: true,
    replyText: labels[command] + ': "<b>' + preview + '</b>"'
  }}];
}

return [{ json: {
  command, content, chatId, messageId, isVoice: false,
  dateStr, timestamp, fileTs, VAULT,
  obsidianContent: '', filepath: '', hasPrefix: false,
  replyText: ''
}}];

const { content: query, chatId, VAULT } = $input.first().json;
const fs = require('fs');
const path = require('path');

if (!query || query.length < 2) {
  return [{ json: { ...$input.first().json,
    replyText: 'Geef een zoekterm op van minimaal 2 tekens.\nVoorbeeld: <code>/zoek project aanpak</code>'
  }}];
}

function searchVault(dir, q, results) {
  if (results.length >= 5) return;
  let entries;
  try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch(e) { return; }
  for (const e of entries) {
    if (results.length >= 5) break;
    if (e.name.startsWith('.')) continue;
    const fp = path.join(dir, e.name);
    if (e.isDirectory()) {
      searchVault(fp, q, results);
    } else if (e.name.endsWith('.md')) {
      try {
        const txt = fs.readFileSync(fp, 'utf8');
        if (txt.toLowerCase().includes(q.toLowerCase())) {
          const lines = txt.split('\n');
          const match = lines.find(l => l.toLowerCase().includes(q.toLowerCase()) && l.trim() && !l.startsWith('---') && !l.startsWith('tags:'));
          const clean = (match || '').trim().replace(/^#+\s*/, '').replace(/[*_`\[\]]/g, '').substring(0, 90);
          const relPath = fp.replace(VAULT + '/', '');
          results.push({ name: e.name.replace('.md', ''), path: relPath, preview: clean });
        }
      } catch(e) {}
    }
  }
}

const results = [];
searchVault(VAULT, query, results);

let replyText;
if (results.length === 0) {
  replyText = 'Geen notities gevonden voor "<b>' + query + '</b>".';
} else {
  const list = results.map((r, i) =>
    (i+1) + '. <b>' + r.name + '</b>' + (r.preview ? '\n   <i>' + r.preview + '</i>' : '')
  ).join('\n\n');
  const meer = results.length === 5 ? ' (toon max. 5)' : '';
  replyText = 'Gevonden voor "<b>' + query + '</b>"' + meer + ':\n\n' + list;
}

return [{ json: { ...$input.first().json, replyText, searchResults: results }}];

const { content, chatId, timestamp, dateStr, VAULT } = $input.first().json;
const fs = require('fs');
const path = require('path');

const dir = path.join(VAULT, 'Dagboek');
if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });

const filepath = path.join(dir, dateStr + '.md');
const entry = '\n## ' + timestamp + '\n\n' + content + '\n';

if (fs.existsSync(filepath)) {
  fs.appendFileSync(filepath, entry, 'utf8');
} else {
  const header = [
    '---',
    'tags:',
    '  - dagboek',
    '  - telegram',
    'datum: ' + dateStr,
    'bron: telegram',
    '---',
    '',
    '# Dagboek ' + dateStr,
    ''
  ].join('\n');
  fs.writeFileSync(filepath, header + entry, 'utf8');
}

return [{ json: {
  ...$input.first().json,
  replyText: 'Dagboek bijgewerkt voor ' + dateStr + '.'
}}];

