const llmRaw = $input.first().json;
const original = $('Parse Command').first().json;
const { timestamp, fileTs, chatId, content, VAULT } = original;

let responseText = '';
if (llmRaw.choices?.[0]?.message?.content) {
  responseText = llmRaw.choices[0].message.content;
} else if (llmRaw.response) {
  responseText = llmRaw.response;
} else if (llmRaw.message?.content) {
  responseText = llmRaw.message.content;
} else {
  responseText = JSON.stringify(llmRaw);
}

let parsed = null;
try {
  const cleaned = responseText.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();
  const jsonMatch = cleaned.match(/\{[\s\S]*\}/);
  if (jsonMatch) parsed = JSON.parse(jsonMatch[0]);
} catch(e) {}

const category = parsed?.category || 'notitie';
const title = (parsed?.title || content.substring(0, 50)).replace(/[\/\\<>:|?*"]/g, '-');
const formattedContent = parsed?.content || content;
const tags = Array.isArray(parsed?.tags) ? parsed.tags : [category, 'telegram'];

const tagsYaml = tags.map(t => '  - ' + t).join('\n');
const obsidianLines = [
  '---',
  'titel: ' + title,
  'tags:',
  tagsYaml,
  'datum: ' + timestamp,
  'bron: telegram',
  'categorie: ' + category,
  '---',
  '',
  '# ' + title,
  '',
  formattedContent
];
const obsidianContent = obsidianLines.join('\n');
const filepath = VAULT + '/Inbox/' + fileTs + '-' + category + '.md';
const preview = title.length > 50 ? title.substring(0, 50) + '...' : title;
const replyText = '[' + category.toUpperCase() + '] Opgeslagen: "<b>' + preview + '</b>"';

return [{ json: {
  ...original,
  obsidianContent, filepath, replyText, category, title
}}];

const { obsidianContent, filepath } = $input.first().json;

if (!obsidianContent || !filepath) {
  throw new Error('Ontbrekende data voor bestandsschrijven: content=' + !!obsidianContent + ', path=' + filepath);
}

const fs = require('fs');
const path = require('path');

const dir = path.dirname(filepath);
if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });

fs.writeFileSync(filepath, obsidianContent, 'utf8');

return [{ json: $input.first().json }];
